@router.get("/sso/saml/tenants/{tenant_id}/sp-metadata.xml")
async def get_tenant_sp_metadata(
    tenant_id: str,
    current_user: User = Depends(get_current_user),
    db: AsyncSession = Depends(get_db)
):
    if current_user.tenant_id != tenant_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to inspect tenant SAML metadata")

    tenant_config = await db.scalar(
        select(TenantSAMLConfig).where(TenantSAMLConfig.tenant_id == tenant_id)
    )
    if not tenant_config:
        raise HTTPException(status_code=404, detail="SAML configuration not found")

    settings = OneLogin_Saml2_Settings(tenant_config.saml_settings_dict)
    metadata = settings.get_sp_metadata()
    errors = settings.validate_metadata(metadata)
    if errors:
        raise HTTPException(status_code=500, detail="Metadata validation failed")

    return Response(content=metadata, media_type="application/xml")
